// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------
export type EnetLogoProps = {
  /** Click handler. */
  onClick?: () => void
  /** When `true`, transitions from the intro pose to the final lockup. */
  animate?: boolean
  /** Delay before each part starts moving (seconds). Maps to `--enet-hold`. */
  holdSeconds?: number
  /** Duration of each part's opacity/transform transition (seconds). */
  revealSeconds?: number
  /** Extra delay between consecutive parts (seconds). */
  staggerSeconds?: number
  /** CSS easing for transitions, e.g. `cubic-bezier(0.71, 0, 0.36, 0.99)`. */
  easeOut?: string
  /** Horizontal split offset for the intro pose (SVG user units / px). */
  splitOffsetPx?: number
  /** Wordmark paths (`systems`, letters, `e`). Omitted: use `.enet-logo { --enet-primary }` or CSS default `#ffffff`. */
  primaryColor?: string
  /** Chevron. Omitted: use `--enet-accent` or default `#28AFA2`. */
  accentColor?: string
  className?: string
  svgClassName?: string
  /** Shown in `<title>` and `aria-label` for the graphic. */
  title?: string
  /** Fires once after the longest transition finishes (or immediately if reduced motion). */
  onAnimationEnd?: () => void
  /** When `true` (default), honors `prefers-reduced-motion: reduce`. */
  respectReducedMotion?: boolean
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const DEFAULT_EASE = 'cubic-bezier(0.71, 0, 0.36, 0.99)'

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    setReduced(mq.matches)
    const onChange = () => setReduced(mq.matches)
    mq.addEventListener('change', onChange)
    return () => mq.removeEventListener('change', onChange)
  }, [])
  return reduced
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------
export function EnetLogo({
  onClick,
  animate = false,
  holdSeconds = 0,
  revealSeconds = 0.55,
  staggerSeconds = 0,
  easeOut = DEFAULT_EASE,
  splitOffsetPx = 240,
  primaryColor,
  accentColor,
  className,
  svgClassName = 'size-full',
  title = 'eNet systems',
  onAnimationEnd,
  respectReducedMotion = true,
}: EnetLogoProps) {
  const reducedMotion = usePrefersReducedMotion()
  const isReduced = Boolean(respectReducedMotion && reducedMotion)

  const [revealed, setRevealed] = useState(false)
  useEffect(() => {
    if (isReduced) {
      setRevealed(animate)
      return
    }
    if (!animate) {
      setRevealed(false)
      return
    }
    let raf1 = 0
    let raf2 = 0
    raf1 = requestAnimationFrame(() => {
      raf2 = requestAnimationFrame(() => setRevealed(true))
    })
    return () => {
      cancelAnimationFrame(raf1)
      cancelAnimationFrame(raf2)
    }
  }, [animate, isReduced])

  const cssVars = useMemo(
    () =>
      ({
        '--enet-hold': `${holdSeconds}s`,
        '--enet-reveal': `${revealSeconds}s`,
        '--enet-ease': easeOut,
        '--enet-stagger': `${staggerSeconds}s`,
        '--enet-split': `${splitOffsetPx}px`,
        ...(primaryColor !== undefined && { '--enet-primary': primaryColor }),
        ...(accentColor !== undefined && { '--enet-accent': accentColor }),
      }) as CSSProperties,
    [accentColor, easeOut, holdSeconds, primaryColor, revealSeconds, splitOffsetPx, staggerSeconds],
  )

  const totalSeconds = holdSeconds + 5 * staggerSeconds + revealSeconds

  useEffect(() => {
    if (!revealed || !onAnimationEnd) return
    if (isReduced) {
      const id = requestAnimationFrame(onAnimationEnd)
      return () => cancelAnimationFrame(id)
    }
    const ms = Math.ceil(totalSeconds * 1000) + 50
    const id = window.setTimeout(onAnimationEnd, ms)
    return () => clearTimeout(id)
  }, [isReduced, onAnimationEnd, revealed, totalSeconds])

  const rootClass = ['enet-logo', revealed ? 'enet-logo--animate-end' : '', className]
    .filter(Boolean)
    .join(' ')

  return (
    <div className={rootClass} style={cssVars} onClick={onClick}>
      <svg
        className={svgClassName}
        width={1488}
        height={700}
        viewBox="0 700 1488 100"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        role="img"
        aria-label={title}
      >
        <title>{title}</title>
        <path d={paths.systems} data-enet-part="systems" fill={primaryColor} />
        <path d={paths['letter-n']} data-enet-part="letter-n" fill={primaryColor} />
        <path d={paths['letter-e']} data-enet-part="letter-e" fill={primaryColor} />
        <path d={paths['letter-t']} data-enet-part="letter-t" fill={primaryColor} />
        <path d={paths.chevron} data-enet-part="chevron" fill={accentColor ?? '#28afa2'} />
        <path d={paths.e} fillRule="evenodd" clipRule="evenodd" data-enet-part="e" fill={primaryColor} />
      </svg>
    </div>
  )
}
